1	package service
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/url"
8	
9		"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
10	)
11	
12	// Query business errors, both recognizable with errors.Is.
13	var (
14		// ErrInvalidPlacementQuery is returned when the parameter set is not one
15		// of the documented combinations. Validation happens before any storage
16		// access, so an invalid query never reaches the model.
17		ErrInvalidPlacementQuery = errors.New("invalid placement query")
18		// ErrPlacementNotFound is returned by the single-record form when the
19		// (namespace, name) identity is unknown.
20		ErrPlacementNotFound = errors.New("placement not found")
21	)
22	
23	// QueryResult carries the outcome of Query. Exactly one field is non-nil on
24	// success: Record for the single-record form, Items for the list form. On
25	// failure both are nil. Items is never nil on a successful list, even when
26	// nothing matched.
27	type QueryResult struct {
28		Record *model.Placement
29		Items  []*model.Placement
30	}
31	
32	// Query is the transport-independent read entry point. values holds the
33	// already-decoded query parameters with duplicates preserved; it is only
34	// read, never modified, and its values are matched exactly as given — no
35	// trimming and no further decoding.
36	//
37	// Only the four documented keys are accepted. With name, namespace is the
38	// only other allowed key and the result is the single stored record or
39	// ErrPlacementNotFound. Without name, namespace, queue and node intersect as
40	// filters, omitted conditions are ignored, and a nil or empty set lists
41	// everything. Lists are ordered by namespace then name in UTF-8 byte order;
42	// a node filter never matches a rejected record. Unknown keys, repeated or
43	// empty values and illegal combinations yield ErrInvalidPlacementQuery, and
44	// any persistence failure yields ErrStorageUnavailable.
45	func (s *Service) Query(ctx context.Context, values url.Values) (QueryResult, error) {
46		params, err := validateQuery(values)
47		if err != nil {
48			return QueryResult{}, err
49		}
50	
51		if name, hasName := params["name"]; hasName {
52			rec, err := s.st.Get(ctx, params["namespace"], name)
53			if errors.Is(err, model.ErrNotFound) {
54				return QueryResult{}, fmt.Errorf("query placement: %w", ErrPlacementNotFound)
55			}
56			if err != nil {
57				return QueryResult{}, queryStorageError(err)
58			}
59			return QueryResult{Record: rec}, nil
60		}
61	
62		recs, err := s.st.List(ctx, model.ListFilter{
63			Namespace: params["namespace"],
64			Queue:     params["queue"],
65			Node:      params["node"],
66		})
67		if err != nil {
68			return QueryResult{}, queryStorageError(err)
69		}
70		if recs == nil {
71			recs = []*model.Placement{}
72		}
73		return QueryResult{Items: recs}, nil
74	}
75	
76	var allowedQueryKeys = map[string]bool{
77		"namespace": true,
78		"name":      true,
79		"queue":     true,
80		"node":      true,
81	}
82	
83	// validateQuery accepts only the four documented keys, each exactly once with
84	// a non-empty value, and only the documented combinations: name requires
85	// namespace and forbids queue and node.
86	func validateQuery(values url.Values) (map[string]string, error) {
87		params := make(map[string]string, len(values))
88		for key, vals := range values {
89			if !allowedQueryKeys[key] || len(vals) != 1 || vals[0] == "" {
90				return nil, fmt.Errorf("query placement: %w", ErrInvalidPlacementQuery)
91			}
92			params[key] = vals[0]
93		}
94		if _, hasName := params["name"]; hasName {
95			_, hasNamespace := params["namespace"]
96			_, hasQueue := params["queue"]
97			_, hasNode := params["node"]
98			if !hasNamespace || hasQueue || hasNode {
99				return nil, fmt.Errorf("query placement: %w", ErrInvalidPlacementQuery)
100			}
101		}
102		return params, nil
103	}
104	
105	func queryStorageError(err error) error {
106		return fmt.Errorf("query placements: %w: %w", ErrStorageUnavailable, err)
107	}
