15	
16	func newTestRouter(t *testing.T) (*store.Store, http.Handler) {
17		t.Helper()
18		st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
19		if err != nil {
20			t.Fatalf("open: %v", err)
21		}
22		t.Cleanup(func() { st.Close() })
23		return st, NewRouter(st)
24	}
25	
26	func doRequest(t *testing.T, h http.Handler, method, target string, body string) *httptest.ResponseRecorder {
27		t.Helper()
28		var reader *bytes.Reader
29		if body != "" {
30			reader = bytes.NewReader([]byte(body))
31		} else {
32			reader = bytes.NewReader(nil)
33		}
34		req := httptest.NewRequest(method, target, reader)
35		req.Header.Set("Content-Type", "application/json")
36		rec := httptest.NewRecorder()
37		h.ServeHTTP(rec, req)
38		return rec
39	}
40	
41	func postPlacement(t *testing.T, h http.Handler, body string) *httptest.ResponseRecorder {
42		t.Helper()
43		return doRequest(t, h, http.MethodPost, "/v1/placements", body)
44	}
45	
46	func decodeBody(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
47		t.Helper()
48		var out map[string]any
49		if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
50			t.Fatalf("decode %q: %v", rec.Body.String(), err)
51		}
52		return out
53	}
54	
55	func expectErrorCode(t *testing.T, rec *httptest.ResponseRecorder, status int, code string) {
56		t.Helper()
57		if rec.Code != status {
58			t.Fatalf("status = %d, want %d; body %s", rec.Code, status, rec.Body.String())
59		}
60		body := decodeBody(t, rec)
61		errObj, ok := body["error"].(map[string]any)
62		if !ok {
63			t.Fatalf("error object missing: %s", rec.Body.String())
64		}
65		if got := errObj["code"]; got != code {
66			t.Fatalf("code = %v, want %s", got, code)
67		}
68		if msg, ok := errObj["message"].(string); !ok || msg == "" {
69			t.Fatalf("message must be a non-empty string: %s", rec.Body.String())
70		}
71		if len(body) != 1 {
72			t.Fatalf("error response must have only the error key: %s", rec.Body.String())
73		}
74	}
75	
76	const validBody = `{
77	  "namespace": "team-a",
78	  "name": "job-1",
79	  "queue": "default",
80	  "priority": 10,
81	  "resources": {"cpu": 500, "memory": 256},
82	  "selector": {"zone": "cn"},
83	  "nodes": [
84	    {"name": "node-b", "cpu": 1000, "memory": 512, "labels": {"zone": "cn", "ssd": "true"}},
85	    {"name": "node-a", "cpu": 1000, "memory": 512, "labels": {"zone": "cn"}},
86	    {"name": "node-c", "cpu": 100, "memory": 128, "labels": {"zone": "cn"}},
87	    {"name": "node-d", "cpu": 1000, "memory": 512, "labels": {"zone": "us"}}
88	  ]
89	}`
90	
91	func TestCreatePlacementSelectsSmallestEligibleNode(t *testing.T) {
92		_, h := newTestRouter(t)
93		rec := postPlacement(t, h, validBody)
94		if rec.Code != http.StatusCreated {
95			t.Fatalf("status = %d, want 201: %s", rec.Code, rec.Body.String())
96		}
97		body := decodeBody(t, rec)
98		if body["status"] != "placed" {
99			t.Fatalf("status = %v, want placed", body["status"])
100		}
101		if body["node"] != "node-a" {
102			t.Fatalf("node = %v, want node-a (byte-smallest eligible; node-c too small, node-d wrong zone)", body["node"])
103		}
104		if body["reason"] != nil {
105			t.Fatalf("reason = %v, want null", body["reason"])
106		}
107		if body["namespace"] != "team-a" || body["queue"] != "default" || body["priority"].(float64) != 10 {
108			t.Fatalf("input fields not retained: %s", rec.Body.String())
109		}
110	}
111	
112	func TestCreatePlacementRejectsWhenNoEligibleNode(t *testing.T) {
113		_, h := newTestRouter(t)
114		body := `{
115		  "namespace": "team-a", "name": "job-2", "queue": "default", "priority": -1,
116		  "resources": {"cpu": 2000, "memory": 256},
117		  "nodes": [{"name": "node-a", "cpu": 1000, "memory": 512, "labels": {}}]
118		}`
119		rec := postPlacement(t, h, body)
120		if rec.Code != http.StatusCreated {
121			t.Fatalf("status = %d, want 201: %s", rec.Code, rec.Body.String())
122		}
123		got := decodeBody(t, rec)
124		if got["status"] != "rejected" || got["node"] != nil || got["reason"] != "no_eligible_node" {
125			t.Fatalf("unexpected decision: %s", rec.Body.String())
126		}
127	}
128	
129	func TestEmptyNodesAndOmittedSelectorDefaultToRejected(t *testing.T) {
130		_, h := newTestRouter(t)
131		body := `{
132		  "namespace": "ns", "name": "job", "queue": "q", "priority": 0,
133		  "resources": {"cpu": 1, "memory": 1}, "nodes": []
134		}`
135		rec := postPlacement(t, h, body)
136		if rec.Code != http.StatusCreated {
137			t.Fatalf("status = %d: %s", rec.Code, rec.Body.String())
138		}
139		got := decodeBody(t, rec)
140		if got["status"] != "rejected" || got["reason"] != "no_eligible_node" {
141			t.Fatalf("want rejected: %s", rec.Body.String())
142		}
143	}
144	
145	func TestRepeatSubmissionIsIdempotent(t *testing.T) {
146		_, h := newTestRouter(t)
147		first := postPlacement(t, h, validBody)
148		if first.Code != http.StatusCreated {
149			t.Fatalf("first status = %d: %s", first.Code, first.Body.String())
